<script setup lang="ts">import{computed,ref}from'vue';import{useSiteStore}from'../stores/site';import MetricCard from'../components/MetricCard.vue';import{runSafeResilienceSelfTests,type ResilienceCheckResult}from'../services/resilience';import{loadRuntimeConfig}from'../runtime-config';const store=useSiteStore();const running=ref(false);const results=ref<ResilienceCheckResult[]>([]);const blocked=ref<string|null>(null);const passCount=computed(()=>results.value.filter(r=>r.status==='PASS').length);async function run(){running.value=true;blocked.value=null;results.value=[];try{const c=await loadRuntimeConfig();if(c.environment==='factory'&&!c.faultInjection?.allowInFactory){blocked.value='当前运行环境不允许执行连接恢复检查。';return;}if(c.faultInjection?.enabled===false){blocked.value='当前未启用连接恢复检查。';return;}results.value=await runSafeResilienceSelfTests(store.dashboard);}finally{running.value=false;}}</script>
<template><section class="operator-page"><p class="eyebrow">恢复管理</p><h1>连接与恢复状态</h1><p class="lead">查看断线重连、数据超时和客户端状态恢复情况。</p><div class="metric-row"><MetricCard label="检查项目" :value="results.length||4" detail="连接与数据状态"/><MetricCard label="正常" :value="passCount" detail="最近一次结果"/><MetricCard label="实时连接" :value="store.realtimeState" :detail="`重连 ${store.realtimeDiagnostics.reconnectCount} 次`"/><MetricCard label="数据超时" :value="store.realtimeDiagnostics.silenceTimeoutCount" detail="累计次数"/></div><div class="panel"><div class="card-head"><div><h2>运行状态检查</h2><p>检查数据过期、重复确认和消息顺序等状态。</p></div><button class="primary-button" :disabled="running" @click="run">{{running?'检查中…':'立即检查'}}</button></div><p v-if="blocked" class="error">{{blocked}}</p><div v-if="results.length" class="table-card embedded"><table><thead><tr><th>项目</th><th>状态</th><th>详情</th><th>耗时</th></tr></thead><tbody><tr v-for="r in results" :key="r.id"><td>{{r.name}}</td><td><span class="status-pill" :class="r.status==='PASS'?'tone-good':'tone-bad'">{{r.status==='PASS'?'正常':'异常'}}</span></td><td>{{r.detail}}</td><td>{{r.durationMs}} ms</td></tr></tbody></table></div></div><div class="panel"><h2>恢复项目</h2><div class="fault-grid"><div><strong>网络连接</strong><span>断线后自动重新连接，并保持数据状态可见。</span></div><div><strong>实时数据</strong><span>长时间未收到数据时标记异常并重新建立连接。</span></div><div><strong>后端服务</strong><span>服务恢复后重新获取设备、报警和最新数据。</span></div><div><strong>边缘节点</strong><span>节点恢复后重新建立通信并同步当前状态。</span></div></div></div></section></template>
